/**
 * Statically bundled OSDR datasets.
 *
 * The JSON is generated by `npm run data:build` and imported at build time, so
 * the browser reads no network resource and no runtime parsing is required.
 * `buildOsdrDataset` is the only writer of this shape; the cast here is limited
 * to the JSON module boundary.
 */

import cbcJson from "../../../data/processed/osdr/osd-569-cbc.json";
import cmpJson from "../../../data/processed/osdr/osd-575-cmp.json";
import cardiovascularJson from "../../../data/processed/osdr/osd-575-cardiovascular.json";
import type { OsdrDataset, OsdrDatasetId } from "../../types/osdr";

export const OSDR_DATASETS: readonly OsdrDataset[] = [
  cmpJson as unknown as OsdrDataset,
  cardiovascularJson as unknown as OsdrDataset,
  cbcJson as unknown as OsdrDataset,
];

const DATASETS_BY_ID: ReadonlyMap<OsdrDatasetId, OsdrDataset> = new Map(
  OSDR_DATASETS.map((dataset) => [dataset.datasetId, dataset]),
);

export function getOsdrDataset(datasetId: OsdrDatasetId): OsdrDataset {
  const dataset = DATASETS_BY_ID.get(datasetId);
  if (!dataset) throw new Error(`Unknown OSDR dataset: ${datasetId}`);
  return dataset;
}
